import collections

def transform(grid):
    if not grid:
        return grid

    # Identify background color (most frequent)
    flat_cells = [cell for row in grid for cell in row]
    bg_count = collections.Counter(flat_cells)
    bg_color = bg_count.most_common(1)[0][0]

    rows = len(grid)
    cols = len(grid[0])

    # Initialize new grid with background
    new_grid = [[bg_color for _ in range(cols)] for _ in range(rows)]

    # Find foreground pixels and determine which to keep based on "gravity" rule
    # Rule: A pixel is removed if it has an 8-connected neighbor with a higher row index.
    # This keeps the "bottom-most" pixel(s) of any structure.
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                keep = True
                # Check all 8 neighbors
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        # Check bounds
                        if 0 <= nr < rows and 0 <= nc < cols:
                            # Check if neighbor is foreground
                            if grid[nr][nc] != bg_color:
                                # Check if neighbor is below (higher index)
                                if nr > r:
                                    keep = False
                                    break
                if keep:
                    new_grid[r][c] = grid[r][c]

    return new_grid
